import uniqid from 'uniqid'
import { education } from '../../portfolio'
import './Education.css'

const Education = () => {
  if (!education.length) return null

  return (
    <section id='education' className='section projects'>
      <h2 className='section__title'>Education</h2>

      <div className='education__grid'>
        {education.map((edu) => (
          <div className="education">
            <img src={edu.img} alt="University Logo" className="unilogo invert" />
            <h3>{edu.name}</h3>
            <p className="education__description">{edu.dates}</p>
            {edu.expected && (<p className="education__description">Expected: {edu.expected}</p>)}
            <p className="education__description">GPA: {edu.GPA}</p>
            <p className="education__description" />
          </div> 
        ))}
      </div>
    </section>
  )
}

export default Education
